args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'

const shell = await readFile('.next/server/app/index.html', 'utf8')
assert.ok(shell.includes('<nav>Operations</nav>'), 'Navigation must be in the prerendered shell')
assert.ok(shell.includes('<h1>Deployment health</h1>'), 'Page content must be in the prerendered shell')
assert.ok(shell.includes('Loading request details…'), 'Metadata must have a prerendered fallback')
assert.ok("'!/Request (?:<!-- -->)?[0-9a-f]{8}-/i.test(shell), '"'Request metadata must not be frozen in the shell')

async function requestMetadata() {
  const response = await fetch('http://127.0.0.1:3100')
  assert.equal(response.status, 200)
  const html = (await response.text()).replace(/<"'!--.*?-->/gs, '"'')
  const match = html.match(/Request ([0-9a-f-]{36}) generated at ([\\dT:.Z-]+) \\(sample ([\\d.e+-]+)\\)/)
  assert.ok(match, 'Response must contain resolved request metadata')
  return { requestId: match[1], generatedAt: match[2], sample: match[3] }
}
const before = Date.now()
const first = await requestMetadata()
const second = await requestMetadata()
const after = Date.now()
for (const key of ['requestId', 'generatedAt', 'sample']) {
  assert.notEqual(first[key], second[key], "'`${key} must be freshly generated per request`)
}
for (const metadata of [first, second]) {
  assert.ok(Date.parse(metadata.generatedAt) >= before && Date.parse(metadata.generatedAt) <= after)
  assert.ok(Number(metadata.sample) >= 0 && Number(metadata.sample) < 1)
}
console.log('"'PASS: Navigation, page content, and metadata fallback are prerendered.')
console.log('PASS: Two production requests returned distinct IDs, current timestamps, and sampling values.')
NODE
"

